input.command:
set -x
W=$(mktemp -d)
cat > "$W/helper.c" <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    if (strcmp(argv[1], "run") == 0) return 0;
    if (strcmp(argv[1], "fork") == 0) {
        int n = argc > 2 ? atoi(argv[2]) : 0;
        int created = 0;
        for (int i = 0; i < n; i++) {
            pid_t pid = fork();
            if (pid == 0) _exit(0);
            if (pid < 0) break;
            created++;
        }
        for (int i = 0; i < created; i++) { int status; wait(&status); }
        printf("%d\n", created);
        return 0;
    }
    if (strcmp(argv[1], "mem") == 0) {
        long mib = argc > 2 ? atol(argv[2]) : 0;
        size_t bytes = (size_t) mib * 1024 * 1024;
        char *buf = malloc(bytes);
        if (!buf) { fprintf(stderr, "malloc fail\n"); return 1; }
        for (size_t i = 0; i < bytes; i += 4096) buf[i] = 1;
        printf("touched %ld\n", mib);
        return 0;
    }
    return 1;
}
EOF
gcc -static -O2 -o "$W/helper" "$W/helper.c"
mkdir -p "$W/rootfs/bin"
cp "$W/helper" "$W/rootfs/bin/helper"
tar -C "$W/rootfs" -cf "$W/rootfs.tar" .
podman import "$W/rootfs.tar" thyrox-test-cap-manual
echo "== run =="
podman run --rm --network none thyrox-test-cap-manual /bin/helper run; echo "rc=$?"
echo "== fork 64 pids-limit 16 =="
podman run --rm --network none --pids-limit 16 thyrox-test-cap-manual /bin/helper fork 64; echo "rc=$?"
echo "== mem 256 memory 64m =="
podman run --rm --network none --memory 64m thyrox-test-cap-manual /bin/helper mem 256; echo "rc=$?"
podman rmi -f thyrox-test-cap-manual
rm -rf "$W"

