input.command:
set -x
W=$(mktemp -d)
cat > "$W/helper.c" <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    if (strcmp(argv[1], "sleep") == 0) {
        unsigned int s = argc > 2 ? (unsigned int) atoi(argv[2]) : 0;
        sleep(s);
        return 0;
    }
    return 1;
}
EOF
gcc -static -O2 -o "$W/helper" "$W/helper.c"
mkdir -p "$W/rootfs/bin"
cp "$W/helper" "$W/rootfs/bin/helper"
tar -C "$W/rootfs" -cf "$W/rootfs.tar" .
podman import "$W/rootfs.tar" thyrox-test-cap-manual2
podman run -d --network none --name thyrox-cleanup-test thyrox-test-cap-manual2 /bin/helper sleep 30
podman inspect -f '{{.State.Pid}}' thyrox-cleanup-test
pgrep -af '[b]in/helper' || echo "no host process found (unexpected before rm)"
podman rm -f thyrox-cleanup-test
podman ps -a --filter "name=^thyrox-cleanup-test$" --format '{{.Names}}'
pgrep -af '[b]in/helper' && echo "STILL RUNNING" || echo "gone after rm -f"
podman rmi -f thyrox-test-cap-manual2
rm -rf "$W"

